CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250830025915_InitialCreate') THEN
    CREATE TABLE "Players" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Game" character varying(50) NOT NULL,
        "Team" character varying(100),
        "BasePrice" numeric(18,2) NOT NULL,
        "CurrentPrice" numeric(18,2) NOT NULL,
        "TotalShares" integer NOT NULL,
        "AvailableShares" integer NOT NULL,
        "Rating" numeric(3,2),
        "PopularityScore" integer NOT NULL,
        "LastUpdated" timestamp with time zone NOT NULL,
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_Players" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250830025915_InitialCreate') THEN
    CREATE TABLE "Teams" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Game" character varying(50) NOT NULL,
        "BasePrice" numeric(18,2) NOT NULL,
        "CurrentPrice" numeric(18,2) NOT NULL,
        "TotalShares" integer NOT NULL,
        "AvailableShares" integer NOT NULL,
        "Ranking" integer,
        "LastUpdated" timestamp with time zone NOT NULL,
        "IsActive" boolean NOT NULL,
        CONSTRAINT "PK_Teams" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250830025915_InitialCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Username" character varying(50) NOT NULL,
        "Email" character varying(100) NOT NULL,
        "PasswordHash" character varying(255) NOT NULL,
        "Balance" numeric(18,2) NOT NULL,
        "Level" integer NOT NULL,
        "TotalTrades" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
        "LastLoginAt" timestamp with time zone,
        "IsActive" boolean NOT NULL,
        "IsEmailVerified" boolean NOT NULL,
        "VerificationToken" text,
        "VerificationTokenExpires" timestamp with time zone,
        "ResetToken" text,
        "ResetTokenExpires" timestamp with time zone,
        "IsKycVerified" boolean NOT NULL,
        "KycStatus" text,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250830025915_InitialCreate') THEN
    CREATE TABLE "Matches" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "PlayerId" integer,
        "TeamId" integer,
        "Opponent" character varying(100),
        "Result" character varying(10),
        "PlayerRating" numeric(3,2),
        "IsMVP" boolean NOT NULL,
        "Tournament" character varying(100),
        "TournamentTier" integer,
        "MatchDate" timestamp with time zone NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
        CONSTRAINT "PK_Matches" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Matches_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Matches_Teams_TeamId" FOREIGN KEY ("TeamId") REFERENCES "Teams" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
